using System;using System.IO;using System.Linq;using System.Drawing;using System.Diagnostics;using System.Threading.Tasks;using System.Collections.Generic;using System.Windows.Forms;using Microsoft.Win32;
namespace HvDacRemoval {
static class Entry {
    static readonly string[] Names={"ART-DAQ","DMC","PicoSDK x64","PicoSDK 64-bit","SX Virtual Link Lite"};
    public sealed class Product{public string Name,Command;}
    public static List<Product> Products(){var list=new List<Product>();foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32})using(var hive=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,view))using(var root=hive.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall")){if(root==null)continue;foreach(var n in root.GetSubKeyNames())using(var k=root.OpenSubKey(n)){string name=k.GetValue("DisplayName") as string;if(!Names.Contains(name))continue;string cmd=k.GetValue("UninstallString") as string;if(!string.IsNullOrEmpty(cmd)&&!list.Any(p=>p.Command==cmd))list.Add(new Product{Name=name,Command=cmd});}}return list;}
    public static List<string> DriverPackages(){return Directory.GetFiles(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"INF"),"oem*.inf").Where(p=>{try{string t=File.ReadAllText(p).ToUpperInvariant();return (t.Contains("VID_3063&PID_3135")&&t.Contains("ART"))||(t.Contains("VID_0CE9&PID_1218")&&t.Contains("PICO"))||(t.Contains("ROOT\\SXUPTP")&&t.Contains("SILEX"));}catch{return false;}}).ToList();}
    static int Run(string exe,string args){using(var p=Process.Start(new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(300000))throw new TimeoutException("卸载仍在运行，停止后续步骤，请手动查看官方窗口；未强制终止。" );return p.ExitCode;}}
    static int Remove(Product p){string cmd=p.Command.Trim();if(cmd.StartsWith("MsiExec",StringComparison.OrdinalIgnoreCase)){var m=System.Text.RegularExpressions.Regex.Match(cmd,@"\{[0-9A-Fa-f-]{36}\}");if(!m.Success)throw new Exception("未识别的 MSI 卸载参数");return Run(Path.Combine(Environment.SystemDirectory,"msiexec.exe"),"/x "+m.Value+" /passive /norestart");}string exe,args;if(cmd.StartsWith("\"")){int end=cmd.IndexOf('"',1);exe=cmd.Substring(1,end-1);args=cmd.Substring(end+1).Trim();}else {int end=cmd.IndexOf(".exe",StringComparison.OrdinalIgnoreCase);if(end<0)throw new Exception("无效卸载命令");exe=cmd.Substring(0,end+4);args=cmd.Substring(end+4).Trim();}if(!File.Exists(exe))throw new FileNotFoundException("官方卸载程序不存在",exe);return Run(exe,args);}
    [STAThread]static void Main(string[] args){Application.EnableVisualStyles();if(args.Contains("--preview")){File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"uninstall-preview.txt"),Products().Select(p=>p.Name+" | "+p.Command).Concat(DriverPackages()));return;}Xiongxin.OWTS.Ui.DialogPlacement.Install();Application.Run(new RemovalForm());}
    sealed class RemovalForm:Form {
        TextBox log=new TextBox{Multiline=true,ReadOnly=true,Dock=DockStyle.Fill,ScrollBars=ScrollBars.Vertical};bool running;
        public RemovalForm(){Text="HV DAC Xpert · 卸载";ClientSize=new Size(900,500);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Microsoft YaHei UI",10);string icon=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","xiongxin.ico");Icon=File.Exists(icon)?new Icon(icon):SystemIcons.Application;
            var note=new Label{Dock=DockStyle.Top,Height=95,Text="仅卸载本软件：保留厂家共享驱动。\r\n完整卸载：移除 DS600 / ART-DAQ / DMC / PicoSDK x64，以及匹配的驱动包。\r\n会影响直连 5242D 和其他共享这些驱动的软件。请停止采集、关闭本套件所有其他程序。"};
            var panel=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=50};var own=new Button{Text="仅卸载本软件",AutoSize=true};var all=new Button{Text="完整卸载（含共享驱动）",AutoSize=true};panel.Controls.Add(own);panel.Controls.Add(all);Controls.Add(log);Controls.Add(note);Controls.Add(panel);
            own.Click+=async delegate{await RemoveAll(false,panel);};all.Click+=async delegate{await RemoveAll(true,panel);};FormClosing+=delegate(object s,FormClosingEventArgs e){if(running)e.Cancel=true;};
            log.Text="待确认厂家组件：\r\n"+string.Join("\r\n",Products().Select(p=>p.Name))+"\r\n匹配驱动包：\r\n"+string.Join("\r\n",DriverPackages().Select(Path.GetFileName));
        }
        void Report(string s){Invoke((Action)(()=>log.AppendText("\r\n"+s)));}
        async Task RemoveAll(bool drivers,Control buttons){if(MessageBox.Show(this,drivers?"确认卸载这些共享驱动？直连 5242D 也将无法使用，重新安装驱动后才能恢复。":"确认删除本目录中本套件登记的程序文件？保留配置、日志和所有厂家驱动。","确认卸载",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;running=true;buttons.Enabled=false;try{await Task.Run(()=>{
            if(drivers){var packages=DriverPackages();string backup=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"HV DAC Xpert","DriverBackup",DateTime.Now.ToString("yyyyMMddHHmmss"));Directory.CreateDirectory(backup);string pnp=Path.Combine(Environment.SystemDirectory,"pnputil.exe");foreach(var inf in packages){int c=Run(pnp,"/export-driver "+Path.GetFileName(inf)+" \""+backup+"\"");if(c!=0)throw new Exception("驱动备份失败，停止卸载："+Path.GetFileName(inf)+" code="+c);}Report("驱动备份："+backup);
                foreach(var product in Products().GroupBy(p=>p.Name).Select(g=>g.OrderByDescending(p=>!p.Command.StartsWith("MsiExec",StringComparison.OrdinalIgnoreCase)).First())){Report("官方卸载："+product.Name);int c=Remove(product);if(c!=0&&c!=3010&&c!=1605)throw new Exception(product.Name+" 未完成，code="+c);}
                foreach(var inf in packages){if(!File.Exists(inf))continue;int c=Run(pnp,"/delete-driver "+Path.GetFileName(inf)+" /uninstall");Report(Path.GetFileName(inf)+" code="+c);if(c!=0&&c!=3010)throw new Exception("驱动包未删除，不强制删除："+Path.GetFileName(inf));}
                if(Products().Count>0||DriverPackages().Count>0){Report("仍有组件/驱动记录，请重启后复查；不能判定完整卸载成功。");return;}
            }
            string root=Path.GetFullPath(AppDomain.CurrentDomain.BaseDirectory);string manifest=Path.Combine(root,"installed-files.txt");if(!File.Exists(manifest)){Report("未找到安装文件清单：不删除调试目录。厂家卸载步骤已结束。");return;}
            var files=File.ReadAllLines(manifest).Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>Path.GetFullPath(Path.Combine(root,x))).ToList();if(files.Any(p=>!p.StartsWith(root,StringComparison.OrdinalIgnoreCase)||p==root))throw new Exception("安装文件清单越界，已停止");
            foreach(var f in files){if(string.Equals(f,Application.ExecutablePath,StringComparison.OrdinalIgnoreCase))continue;if(File.Exists(f))File.Delete(f);}Report("已删除清单内程序文件；保留卸载程序自身、配置和日志。驱动如要求重启，请手动重启后复查。");
        });}catch(Exception ex){log.AppendText("\r\n未完成："+ex.Message);}finally{running=false;buttons.Enabled=true;}}
    }
}
}
